<?php
declare(strict_types=1);

namespace App\Infrastructure\Persistence;

use App\Application\Read\Page;
use App\Application\Repositories\PurchasingRepository;
use PDO;

final class PdoPurchasingRepository extends PdoRepository implements PurchasingRepository
{
    public function suppliers(string $search,string $status,int $limit,int $offset):Page
    {
        [$limit,$offset]=self::pageBounds($limit,$offset);$search=trim($search);if(strlen($search)>120)throw new \InvalidArgumentException('La búsqueda es demasiado larga.');$where=[];$params=[];
        if($search!==''){$where[]='(s.code LIKE :q1 OR s.legal_name LIKE :q2 OR s.tax_identifier LIKE :q3)';$term='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$search).'%';$params=['q1'=>$term,'q2'=>$term,'q3'=>$term];}
        if($status==='active')$where[]='s.is_active=1';elseif($status==='inactive')$where[]='s.is_active=0';elseif($status!=='all')throw new \InvalidArgumentException('El estado no es válido.');
        $sql='SELECT s.*,c.name contact_name,c.phone contact_phone,c.email contact_email,(SELECT COUNT(*) FROM supplier_invoices si WHERE si.supplier_id=s.id) invoice_count FROM suppliers s LEFT JOIN supplier_contacts c ON c.supplier_id=s.id AND c.is_primary=1'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY s.legal_name,s.id LIMIT :limit OFFSET :offset';
        $st=$this->pdo()->prepare($sql);foreach($params as$k=>$v)$st->bindValue($k,$v);$st->bindValue('limit',$limit+1,PDO::PARAM_INT);$st->bindValue('offset',$offset,PDO::PARAM_INT);$st->execute();$rows=$st->fetchAll();$more=count($rows)>$limit;if($more)array_pop($rows);return new Page($rows,$limit,$offset,$more);
    }
    public function activeSuppliers():array{return $this->pdo()->query('SELECT id,code,legal_name FROM suppliers WHERE is_active=1 ORDER BY legal_name,id LIMIT 1000')->fetchAll();}
    public function supplier(int$id,bool$lock=false):?array{$st=$this->pdo()->prepare('SELECT s.*,c.name contact_name,c.phone contact_phone,c.email contact_email FROM suppliers s LEFT JOIN supplier_contacts c ON c.supplier_id=s.id AND c.is_primary=1 WHERE s.id=:id'.($lock?' FOR UPDATE':''));$st->execute(['id'=>self::id($id)]);$row=$st->fetch();return$row===false?null:$row;}
    public function createSupplier(array$d):int{return $this->safely(function()use($d):int{$st=$this->pdo()->prepare('INSERT INTO suppliers(code,legal_name,tax_identifier,phone,email,address,is_active,created_by,updated_by) VALUES(:code,:legal_name,:tax_identifier,:phone,:email,:address,1,:actor,:actor2)');$st->execute($d);return$this->insertedId();},'Unable to create supplier.');}
    public function updateSupplier(int$id,array$d):void{$d['id']=self::id($id);$st=$this->pdo()->prepare('UPDATE suppliers SET code=:code,legal_name=:legal_name,tax_identifier=:tax_identifier,phone=:phone,email=:email,address=:address,updated_by=:actor WHERE id=:id');$st->execute($d);if($st->rowCount()>1)throw new \RuntimeException('No fue posible actualizar el proveedor.');}
    public function setSupplierActive(int$id,bool$active,int$actorId):void{$st=$this->pdo()->prepare('UPDATE suppliers SET is_active=:active,updated_by=:actor WHERE id=:id');$st->execute(['active'=>$active?1:0,'actor'=>self::id($actorId),'id'=>self::id($id)]);if($st->rowCount()>1)throw new \RuntimeException('No fue posible cambiar el estado.');}
    public function savePrimaryContact(int$supplierId,?array$c):void{$supplierId=self::id($supplierId);if($c===null){$st=$this->pdo()->prepare('DELETE FROM supplier_contacts WHERE supplier_id=:supplier AND is_primary=1');$st->execute(['supplier'=>$supplierId]);return;}$c['supplier']=$supplierId;$st=$this->pdo()->prepare('INSERT INTO supplier_contacts(supplier_id,name,phone,email,is_primary) VALUES(:supplier,:name,:phone,:email,1) ON DUPLICATE KEY UPDATE name=VALUES(name),phone=VALUES(phone),email=VALUES(email)');$st->execute($c);}
    public function invoices(string$search,?int$branchId,?int$supplierId,string$status,?string$from,?string$until,int$limit,int$offset):Page
    {
        [$limit,$offset]=self::pageBounds($limit,$offset);$where=[];$p=[];$search=trim($search);if(strlen($search)>120)throw new \InvalidArgumentException('La búsqueda es demasiado larga.');if($search!==''){$where[]='(si.folio LIKE :q1 OR si.series LIKE :q2 OR s.legal_name LIKE :q3)';$t='%'.$search.'%';$p+=['q1'=>$t,'q2'=>$t,'q3'=>$t];}if($branchId!==null){$where[]='si.branch_id=:branch';$p['branch']=self::id($branchId);}if($supplierId!==null){$where[]='si.supplier_id=:supplier';$p['supplier']=self::id($supplierId);}if($status!=='all'){$where[]='si.status=:status';$p['status']=$status;}if($from!==null){$where[]='si.document_date>=:from_date';$p['from_date']=$from;}if($until!==null){$where[]='si.document_date<=:until_date';$p['until_date']=$until;}
        $sql='SELECT si.*,s.code supplier_code,s.legal_name supplier_name,b.name branch_name,(SELECT COUNT(*) FROM supplier_invoice_items ii WHERE ii.invoice_id=si.id) item_count FROM supplier_invoices si INNER JOIN suppliers s ON s.id=si.supplier_id INNER JOIN branches b ON b.id=si.branch_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY si.document_date DESC,si.id DESC LIMIT :limit OFFSET :offset';$st=$this->pdo()->prepare($sql);foreach($p as$k=>$v)$st->bindValue($k,$v,is_int($v)?PDO::PARAM_INT:PDO::PARAM_STR);$st->bindValue('limit',$limit+1,PDO::PARAM_INT);$st->bindValue('offset',$offset,PDO::PARAM_INT);$st->execute();$rows=$st->fetchAll();$more=count($rows)>$limit;if($more)array_pop($rows);return new Page($rows,$limit,$offset,$more);
    }
    public function invoice(int$id,bool$lock=false):?array{$st=$this->pdo()->prepare('SELECT si.*,s.code supplier_code,s.legal_name supplier_name,s.is_active supplier_active,b.name branch_name FROM supplier_invoices si INNER JOIN suppliers s ON s.id=si.supplier_id INNER JOIN branches b ON b.id=si.branch_id WHERE si.id=:id'.($lock?' FOR UPDATE':''));$st->execute(['id'=>self::id($id)]);$row=$st->fetch();return$row===false?null:$row;}
    public function invoiceItems(int$id,bool$lock=false):array{$st=$this->pdo()->prepare('SELECT ii.*,p.name product_name,pv.sku,pv.name variant_name,u.name unit_name,u.symbol,u.decimal_places,(ii.invoiced_quantity-ii.received_quantity) pending_quantity,(SELECT ii2.unit_cost FROM supplier_invoice_items ii2 INNER JOIN supplier_invoices si2 ON si2.id=ii2.invoice_id WHERE si2.supplier_id=si.supplier_id AND ii2.variant_id=ii.variant_id AND si2.id<>si.id AND si2.status IN(\'pending\',\'partial\',\'received\') ORDER BY si2.document_date DESC,si2.id DESC,ii2.id DESC LIMIT 1) previous_unit_cost FROM supplier_invoice_items ii INNER JOIN supplier_invoices si ON si.id=ii.invoice_id INNER JOIN product_variants pv ON pv.id=ii.variant_id INNER JOIN products p ON p.id=pv.product_id INNER JOIN units u ON u.id=ii.unit_id WHERE ii.invoice_id=:invoice ORDER BY ii.line_number,ii.id'.($lock?' FOR UPDATE':''));$st->execute(['invoice'=>self::id($id)]);return$st->fetchAll();}
    public function receipts(int$id):array{$st=$this->pdo()->prepare('SELECT gr.*,u.display_name receiver_name,COUNT(gri.id) item_count FROM goods_receipts gr INNER JOIN users u ON u.id=gr.received_by INNER JOIN goods_receipt_items gri ON gri.receipt_id=gr.id WHERE gr.invoice_id=:invoice GROUP BY gr.id,u.display_name ORDER BY gr.received_at DESC,gr.id DESC');$st->execute(['invoice'=>self::id($id)]);return$st->fetchAll();}
    public function createInvoice(array$d):int{return$this->safely(function()use($d):int{$st=$this->pdo()->prepare('INSERT INTO supplier_invoices(supplier_id,branch_id,series,folio,document_date,fiscal_uuid,currency,subtotal,tax_amount,total,status,notes,created_by) VALUES(:supplier_id,:branch_id,:series,:folio,:document_date,:fiscal_uuid,\'MXN\',:subtotal,:tax_amount,:total,\'draft\',:notes,:actor)');$st->execute($d);return$this->insertedId();},'Unable to create supplier invoice.');}
    public function updateInvoice(int$id,array$d):void{$d['id']=self::id($id);$st=$this->pdo()->prepare('UPDATE supplier_invoices SET series=:series,folio=:folio,document_date=:document_date,fiscal_uuid=:fiscal_uuid,subtotal=:subtotal,tax_amount=:tax_amount,total=:total,notes=:notes WHERE id=:id AND status=\'draft\'');$st->execute($d);if($st->rowCount()>1)throw new \RuntimeException('No fue posible actualizar la factura.');}
    public function addInvoiceItem(array$d):int{return$this->safely(function()use($d):int{$st=$this->pdo()->prepare('INSERT INTO supplier_invoice_items(invoice_id,line_number,variant_id,description,unit_id,invoiced_quantity,unit_cost,line_subtotal) VALUES(:invoice_id,:line_number,:variant_id,:description,:unit_id,:invoiced_quantity,:unit_cost,:line_subtotal)');$st->execute($d);return$this->insertedId();},'Unable to add invoice item.');}
    public function removeInvoiceItem(int$itemId,int$invoiceId):void{$st=$this->pdo()->prepare('DELETE FROM supplier_invoice_items WHERE id=:id AND invoice_id=:invoice');$st->execute(['id'=>self::id($itemId),'invoice'=>self::id($invoiceId)]);}
    public function confirmInvoice(int$id,int$actor):void{$st=$this->pdo()->prepare("UPDATE supplier_invoices SET status='pending',confirmed_by=:actor,confirmed_at=CURRENT_TIMESTAMP(6) WHERE id=:id AND status='draft'");$st->execute(['actor'=>self::id($actor),'id'=>self::id($id)]);if($st->rowCount()!==1)throw new \RuntimeException('No fue posible confirmar la factura.');}
    public function updateInvoiceProgress(int$id,string$status):void{$st=$this->pdo()->prepare('UPDATE supplier_invoices SET status=:status WHERE id=:id');$st->execute(['status'=>$status,'id'=>self::id($id)]);}
    public function incrementReceived(int$id,string$q):void{$st=$this->pdo()->prepare('UPDATE supplier_invoice_items SET received_quantity=received_quantity+:quantity_update WHERE id=:id AND received_quantity+:quantity_check<=invoiced_quantity');$st->execute(['quantity_update'=>$q,'quantity_check'=>$q,'id'=>self::id($id)]);if($st->rowCount()!==1)throw new \RuntimeException('La cantidad pendiente cambió durante la recepción.');}
    public function receiptByOperation(string$key):?array{$st=$this->pdo()->prepare('SELECT * FROM goods_receipts WHERE operation_key=:operation_key');$st->execute(['operation_key'=>$key]);$row=$st->fetch();return$row===false?null:$row;}
    public function createReceipt(array$d):int{return$this->safely(function()use($d):int{$st=$this->pdo()->prepare("INSERT INTO goods_receipts(invoice_id,branch_id,operation_key,request_hash,status,notes,received_by) VALUES(:invoice_id,:branch_id,:operation_key,:request_hash,'confirmed',:notes,:received_by)");$st->execute($d);return$this->insertedId();},'Unable to create goods receipt.');}
    public function createReceiptItem(array$d):void{$st=$this->pdo()->prepare('INSERT INTO goods_receipt_items(receipt_id,invoice_item_id,input_quantity,base_quantity,inventory_movement_id) VALUES(:receipt_id,:invoice_item_id,:input_quantity,:base_quantity,:inventory_movement_id)');$st->execute($d);}
    public function branches():array{return$this->pdo()->query('SELECT id,code,name,is_active FROM branches WHERE is_active=1 ORDER BY name,id LIMIT 1000')->fetchAll();}
    public function variants(string$q=''):array{$q=trim($q);if(strlen($q)>120)throw new \InvalidArgumentException('La búsqueda es demasiado larga.');$t='%'.$q.'%';$st=$this->pdo()->prepare('SELECT pv.id,pv.sku,pv.name,pv.unit_id,p.name product_name,u.name unit_name,u.symbol FROM product_variants pv INNER JOIN products p ON p.id=pv.product_id INNER JOIN units u ON u.id=pv.unit_id WHERE pv.is_active=1 AND p.is_active=1 AND (:empty=1 OR pv.sku LIKE :q1 OR pv.name LIKE :q2 OR p.name LIKE :q3) ORDER BY p.name,pv.sku LIMIT 500');$st->execute(['empty'=>$q===''?1:0,'q1'=>$t,'q2'=>$t,'q3'=>$t]);return$st->fetchAll();}
    public function unitsForVariant(int$id):array{$st=$this->pdo()->prepare('SELECT u.id,u.name,u.symbol,u.decimal_places,1.000000 factor,1 is_base FROM product_variants pv INNER JOIN units u ON u.id=pv.unit_id WHERE pv.id=:v1 UNION ALL SELECT u.id,u.name,u.symbol,u.decimal_places,uc.factor,0 is_base FROM unit_conversions uc INNER JOIN units u ON u.id=uc.from_unit_id AND u.is_active=1 WHERE uc.variant_id=:v2 AND uc.to_unit_id=(SELECT unit_id FROM product_variants WHERE id=:v3) ORDER BY is_base DESC,name,id');$st->execute(['v1'=>self::id($id),'v2'=>$id,'v3'=>$id]);return$st->fetchAll();}
    public function variantUnitMeta(int$v,int$u):?array{$st=$this->pdo()->prepare('SELECT pv.id,pv.unit_id base_unit_id,pv.is_active variant_active,p.is_active product_active,bu.decimal_places base_precision,iu.decimal_places input_precision,iu.is_active input_unit_active,uc.factor FROM product_variants pv INNER JOIN products p ON p.id=pv.product_id INNER JOIN units bu ON bu.id=pv.unit_id INNER JOIN units iu ON iu.id=:unit LEFT JOIN unit_conversions uc ON uc.variant_id=pv.id AND uc.from_unit_id=iu.id AND uc.to_unit_id=pv.unit_id WHERE pv.id=:variant');$st->execute(['unit'=>self::id($u),'variant'=>self::id($v)]);$row=$st->fetch();return$row===false?null:$row;}
}
